#!/usr/bin/env python3
"""Fetch Paul Graham essays and create an audiobook MP3 via TTS."""

import html
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import urllib.error
import urllib.request
from html.parser import HTMLParser
from typing import List, Tuple

ESSAYS: List[Tuple[str, str]] = [
    ("Do Things that Don't Scale", "https://www.paulgraham.com/ds.html"),
    ("Founder Mode", "https://www.paulgraham.com/foundermode.html"),
]

OUTPUT_PATH = "/root/audiobook.mp3"


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self._parts = []
        self._skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self._skip += 1
            return
        if tag in ("p", "br", "hr", "h1", "h2", "h3", "h4", "h5", "h6", "li", "blockquote", "div", "tr"):
            self._parts.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            if self._skip:
                self._skip -= 1
            return
        if tag in ("p", "li", "blockquote", "div", "tr"):
            self._parts.append("\n")

    def handle_data(self, data):
        if self._skip:
            return
        self._parts.append(data)

    def get_text(self) -> str:
        return html.unescape("".join(self._parts))


def fetch_html(url: str) -> str:
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req) as resp:
        return resp.read().decode("utf-8", errors="ignore")


def html_to_text(html_doc: str) -> str:
    parser = TextExtractor()
    parser.feed(html_doc)
    text = parser.get_text()
    return text


def verify_content(text: str, expected_min_chars: int = 1500) -> bool:
    return len(text) >= expected_min_chars


def clean_text_for_tts(text: str) -> str:
    # Remove URLs
    text = re.sub(r"http[s]?://\S+", "", text)
    # Remove bracketed footnote markers
    text = re.sub(r"\[\d+\]", "", text)
    # Normalize whitespace
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s+\n", "\n\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    text = text.strip()
    # Remove stray non-printing chars
    text = "".join(ch for ch in text if ch.isprintable() or ch in "\n\t")
    return text


def chunk_text(text: str, max_chars: int = 3800) -> List[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if not sentence:
            continue
        if len(current) + len(sentence) + 1 <= max_chars:
            current = f"{current} {sentence}".strip()
        else:
            if current:
                chunks.append(current)
            current = sentence
    if current:
        chunks.append(current)
    return chunks


def post_json(url: str, headers: dict, payload: dict) -> bytes:
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req) as resp:
            return resp.read()
    except urllib.error.HTTPError as e:
        error_body = e.read().decode("utf-8", errors="ignore")
        raise RuntimeError(f"HTTP {e.code}: {error_body}") from e


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/tts_chunk_{i:03d}.mp3"
        payload = {
            "model": "gpt-4o-mini-tts",
            "input": chunk,
            "voice": "onyx",
            "response_format": "mp3",
        }
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        audio = post_json("https://api.openai.com/v1/audio/speech", headers, payload)
        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)
        print(f"Generated chunk {i + 1}/{len(chunks)}")

    return concatenate_audio(audio_files, output_path)


def find_local_tts() -> str:
    for cmd in ("espeak", "espeak-ng", "pico2wave"):
        if shutil.which(cmd):
            return cmd
    return ""


def create_with_local_tts(text: str, output_path: str) -> bool:
    tts_cmd = find_local_tts()
    if not tts_cmd:
        print("No local TTS engine found.")
        return False

    chunks = chunk_text(text, max_chars=2000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_wav = f"/tmp/tts_chunk_{i:03d}.wav"
        if tts_cmd in ("espeak", "espeak-ng"):
            cmd = [tts_cmd, "-w", chunk_wav, chunk]
        else:
            cmd = [tts_cmd, "-w", chunk_wav, chunk]
        subprocess.run(cmd, check=True)
        audio_files.append(chunk_wav)
        print(f"Generated local chunk {i + 1}/{len(chunks)}")

    return concatenate_audio(audio_files, output_path)


def concatenate_audio(audio_files: List[str], output_path: str) -> bool:
    if not audio_files:
        return False
    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_file, "-c", "copy", output_path],
        capture_output=True,
        text=True,
    )

    for fpath in audio_files:
        try:
            os.unlink(fpath)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass

    if result.returncode != 0:
        sys.stderr.write(result.stderr)
        return False
    return True


def build_combined_text() -> str:
    combined = []
    for title, url in ESSAYS:
        print(f"Fetching: {title}")
        html_doc = fetch_html(url)
        text = html_to_text(html_doc)
        if not verify_content(text):
            print(f"Warning: content for '{title}' may be truncated ({len(text)} chars)")
        cleaned = clean_text_for_tts(text)
        combined.append(f"Essay: {title}. By Paul Graham.\n\n{cleaned}\n\nEnd of essay: {title}.")
    return "\n\n".join(combined)


def main() -> int:
    text = build_combined_text()
    print(f"Total text length: {len(text)} characters")

    success = False
    try:
        if os.environ.get("OPENAI_API_KEY"):
            print("Using OpenAI TTS")
            success = create_with_openai(text, OUTPUT_PATH)
        else:
            print("OpenAI API key not found; trying local TTS")
            success = create_with_local_tts(text, OUTPUT_PATH)
    except Exception as exc:
        print(f"OpenAI TTS failed: {exc}")
        print("Falling back to local TTS")
        success = create_with_local_tts(text, OUTPUT_PATH)

    if success:
        print(f"Audiobook created at {OUTPUT_PATH}")
        return 0

    print("Failed to create audiobook")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
